}

export default function TransactionTable({ transactions, loading }: Props) {
 if (loading) {
 return <p className="txn-table__loading">Loading...</p>;
 }
 if (!transactions.length) {
 return <p className="txn-table__empty">No transactions found.</p>;
 }

 return (
 <div className="txn-table__wrapper">
 <table className="txn-table">
 <thead>
 <tr>
 <th>Number</th>
 <th>Date</th>
 <th>Type</th>
 <th>Description</th>
 <th>Amount</th>
 <th>Balance After</th>
 <th>Status</th>
 </tr>
 </thead>
 <tbody>
 {transactions.map((t) => (
 <tr key={t.sys_id.value}>
 <td>{t.number.display_value}</td>
 <td>{t.timestamp.display_value}</td>
 <td>{t.type.display_value}</td>
 <td>{t.description.display_value}</td>
 <td className="txn-table__amount">{t.amount.display_value}</td>
 <td className="txn-table__amount">
 {t.balance_after.display_value}
 </td>
 <td>
 <span
 className={`txn-status txn-status--${t.status.value}`}
 >
 {t.status.display_value}
 </span>
 </td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 );
}
","/* ── Page Layout ── */
.my-accounts {
 max-width: 1100px;
 margin: 0 auto;
 padding: 24px 32px;
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
}

.my-accounts__title {
 font-size: 24px;
 font-weight: 600;
 margin: 0 0 24px;
 display: flex;
 align-items: center;
 gap: 10px;
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
}

.my-accounts__title-icon {
 font-size: 28px;
}

.my-accounts__loading {
 color: rgb(var(--now-color--text-tertiary, 117, 117, 117));
 font-size: 14px;
 padding: 16px 0;
}

/* ── Account Selector ── */
.my-accounts__selector {
 max-width: 420px;
 margin-bottom: 20px;
}

/* ── Account Details Bar ── */
.my-accounts__details {
 display: flex;
 gap: 24px;
 flex-wrap: wrap;
 padding: 12px 16px;
 margin-bottom: 24px;
 background: rgb(var(--now-color--background-secondary, 243, 243, 243));
 border: 1px solid rgb(var(--now-color--divider-secondary, 218, 220, 224));
 border-radius: 8px;
 font-size: 14px;
 color: rgb(var(--now-color--text-secondary, 66, 80, 92));
}

.my-accounts__details span {
 font-weight: 500;
}

/* ── Section Header ── */
.my-accounts__section-title {
 font-size: 18px;
 font-weight: 600;
 margin: 0 0 16px;
 padding-bottom: 8px;
 border-bottom: 1px solid rgb(var(--now-color--divider-secondary, 218, 220, 224));
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
}

/* ── Transaction Filters ── */
.txn-filters {
 margin-bottom: 20px;
 padding: 16px;
 background: rgb(var(--now-color--background-secondary, 243, 243, 243));
 border: 1px solid rgb(var(--now-color--divider-secondary, 218, 220, 224));
 border-radius: 8px;
}

.txn-filters__row {
 display: flex;
 gap: 24px;
 flex-wrap: wrap;
 margin-bottom: 12px;
}

.txn-filters__group {
 display: flex;
 align-items: flex-end;
 gap: 8px;
}

.txn-filters__label {
 font-weight: 600;
 font-size: 14px;
 padding-bottom: 8px;
 min-width: 36px;
 color: rgb(var(--now-color--text-secondary, 66, 80, 92));
}

.txn-filters__actions {
 display: flex;
 align-items: flex-end;
 gap: 16px;
 flex-wrap: wrap;
}

.txn-filters__search {
 flex: 1;
 min-width: 200px;
 max-width: 400px;
}

/* ── Transaction Table ── */
.txn-table__loading,
.txn-table__empty {
 text-align: center;
 padding: 32px 16px;
 color: rgb(var(--now-color--text-tertiary, 117, 117, 117));
 font-size: 14px;
}

.txn-table__wrapper {
 overflow-x: auto;
 border: 1px solid rgb(var(--now-color--divider-secondary, 218, 220, 224));
 border-radius: 8px;
}

.txn-table {
 width: 100%;
 border-collapse: collapse;
 font-size: 14px;
}

.txn-table thead th {
 text-align: left;
 padding: 10px 12px;
 font-weight: 600;
 font-size: 12px;
 text-transform: uppercase;
 letter-spacing: 0.5px;
 color: rgb(var(--now-color--text-secondary, 66, 80, 92));
 background: rgb(var(--now-color--background-tertiary, 227, 229, 232));
 border-bottom: 2px solid rgb(var(--now-color--divider-primary, 189, 193, 198));
}

.txn-table tbody td {
 padding: 10px 12px;
 border-bottom: 1px solid rgb(var(--now-color--divider-secondary, 218, 220, 224));
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
}

.txn-table tbody tr:hover {
 background: rgb(var(--now-color--background-secondary, 243, 243, 243));
}

.txn-table__amount {
 text-align: right;
 font-variant-numeric: tabular-nums;
}

/* ── Status Badges ── */
.txn-status {
 display: inline-block;
 padding: 2px 10px;
 border-radius: 12px;
 font-size: 12px;
 font-weight: 600;
 white-space: nowrap;
}

.txn-status--complete,
.txn-status--completed {
 background: rgb(var(--now-color--alert-positive-2, 220, 245, 220));
 color: rgb(var(--now-color--alert-positive-3, 30, 100, 30));
}

.txn-status--pending {
 background: rgb(var(--now-color--alert-warning-2, 255, 245, 210));
 color: rgb(var(--now-color--alert-warning-3, 140, 100, 10));
}

.txn-status--failed {
 background: rgb(var(--now-color--alert-critical-2, 255, 220, 220));
 color: rgb(var(--now-color--alert-critical-3, 180, 30, 30));
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useEffect } from "react";
import { Select } from "@servicenow/react-components/Select";
import { fetchAccounts, fetchTransactions } from "./api";
import TransactionFilters from "./TransactionFilters";
import TransactionTable from "./TransactionTable";
import "./app.css";

const now = new Date();
const CUR_MONTH = String(now.getMonth() + 1).padStart(2, "0");
const CUR_YEAR = String(now.getFullYear());

export default function App() {
 const [accounts, setAccounts] = useState<any[]>([]);
 const [selectedId, setSelectedId] = useState("");
 const [transactions, setTransactions] = useState<any[]>([]);
 const [acctLoading, setAcctLoading] = useState(true);
 const [txnLoading, setTxnLoading] = useState(false);
 const [fromMonth, setFromMonth] = useState(CUR_MONTH);
 const [fromYear, setFromYear] = useState(CUR_YEAR);
 const [toMonth, setToMonth] = useState(CUR_MONTH);
 const [toYear, setToYear] = useState(CUR_YEAR);
 const [search, setSearch] = useState("");

 useEffect(() => {
 document.title = "My Accounts";
 fetchAccounts().then((data) => {
 setAccounts(data);
 setAcctLoading(false);
 });
 }, []);

 const loadTxns = async (
 acctId: string, fm: string, fy: string,
 tm: string, ty: string, s: string
 ) => {
 if (!acctId) return;
 setTxnLoading(true);
 const lastDay = new Date(parseInt(ty), parseInt(tm), 0).getDate();
 const from = `${fy}-${fm}-01`;
 const to = `${ty}-${tm}-${String(lastDay).padStart(2, "0")}`;
 const data = await fetchTransactions(acctId, from, to, s);
 setTransactions(data);
 setTxnLoading(false);
 };

 const onAccountChange = (id: string) => {
 setSelectedId(id);
 setTransactions([]);
 loadTxns(id, fromMonth, fromYear, toMonth, toYear, search);
 };

 const onApply = () =>
 loadTxns(selectedId, fromMonth, fromYear, toMonth, toYear, search);

 const selectedAcct = accounts.find((a) => a.sys_id.value === selectedId);

 const acctItems = accounts.map((a) => ({
 id: a.sys_id.value,
 label: a.number.display_value + " - " + a.account_type.display_value,
 }));

 return (
 <div className="my-accounts">
 <h1 className="my-accounts__title">
 <span className="my-accounts__title-icon">🏦</span> My Accounts
 </h1>

 {acctLoading ? (
 <p className="my-accounts__loading">Loading...</p>
 ) : (
 <>
 <div className="my-accounts__selector">
 <Select
 label="Account"
 items={acctItems}
 selectedItem={selectedId}
 onSelectedItemSet={(e: any) => onAccountChange(e.detail.item.id)}
 />
 </div>

 {selectedAcct && (
 <div className="my-accounts__details">
 <span>Type: {selectedAcct.account_type.display_value}</span>
 <span>Balance: {selectedAcct.balance.display_value}</span>
 <span>
 Status:{" "}
 {selectedAcct.active.display_value === "true"
 ? "Active"
 : "Inactive"}
 </span>
 </div>
 )}

 {selectedId && (
 <>
 <h2 className="my-accounts__section-title">Transactions</h2>
 <TransactionFilters
 fromMonth={fromMonth} fromYear={fromYear}
 toMonth={toMonth} toYear={toYear}
 searchText={search}
 onFromMonthChange={setFromMonth}
 onFromYearChange={setFromYear}
 onToMonthChange={setToMonth}
 onToYearChange={setToYear}
 onSearchChange={setSearch}
 onApply={onApply}
 />
 <TransactionTable
 transactions={transactions}
 loading={txnLoading}
 />
 </>
 )}
 </>
 )}
 </div>
 );
}
","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";

ReactDOM.createRoot(document.getElementById("root")!).render(<App />);
